# -*- coding: utf-8 -*-
from en1 import EN, E
E("pm-awas-yojana-gramin", name="Pradhan Mantri Awas Yojana – Gramin (PMAY-G)", short="Assistance up to ₹1.20 lakh (₹1.30 lakh in hilly/North-East areas) to build a pucca house in rural areas.", tag="Housing", ministry="Ministry of Rural Development",
 facts=[("Assistance (plains)","₹1,20,000"),("Hilly / North-East","₹1,30,000"),("Toilet support","₹12,000 (Swachh Bharat Mission-Gramin)"),("MGNREGA labour","90 days (plains), 95 days (hilly/North-East)")],
 about="PMAY-G aims to give pucca houses to eligible rural families living in kutcha houses or without a home. Beneficiaries are chosen mainly from the Socio-Economic Caste Census (SECC) 2011 list and the Awaas+ survey for left-out families. Assistance comes in three instalments directly to the bank account.",
 benefits=["₹1.20 lakh (plains) / ₹1.30 lakh (hilly and North-East states)","Three instalments: ₹25,000 on sanction, ₹45,000 at lintel level, ₹50,000 on roof completion","Separate ₹12,000 for a toilet","90/95 days of unskilled labour under MGNREGA"],
 elig=["Selection is mainly from the SECC 2011 list; left-out families can join via the Awaas+ 2024 survey","Priority: those in kutcha houses, homeless families, manual scavengers, primitive tribal groups, freed bonded labourers","At least 60% of the total target is for SC/ST families"],
 notelig=["Family owns a motorised two/three/four-wheeler or mechanised farm equipment","KCC limit of ₹50,000 or more","Any member earning above ₹15,000 a month, a government employee, or paying income/professional tax","Family with a registered non-farm enterprise","More than 2.5 acres irrigated or 5 acres unirrigated land","Those who already have a house with pucca roof and walls"],
 docs=["Aadhaar card","Aadhaar-linked bank account","BPL card or MGNREGA job card","Land papers (if any)","Caste certificate (for SC/ST)","Mobile number and passport photo"],
 steps=["There is no direct online application. First ask at the Gram Panchayat or Block office (BDO) whether your name is on the list","If not, get your name added through the Awaas+ 2024 survey; officials enter details on the AwaasSoft portal","Or do a self-survey on the 'AwaasPlus 2024' mobile app with Aadhaar and face authentication and note the registration number","After verification and state approval, if your name is on the list the house is sanctioned (the survey does not guarantee a house)","Check status on pmayg.nic.in under 'Stakeholders' → 'IAY/PMAYG Beneficiary' with your registration number"],
 link_label="pmayg.nic.in – official portal", helpline="",
 faq=[("How much money does PMAY-G give?","₹1.20 lakh in plains and ₹1.30 lakh in hilly/North-East states, in three instalments, plus ₹12,000 for a toilet."),("Does applying cost money?","No. There is no charge to apply or to get your name added. Anyone asking for money is cheating; complain to the Gram Panchayat/BDO."),("How to check my status?","On pmayg.nic.in search the beneficiary by registration number, or choose state-district-block-panchayat and search by name/Aadhaar.")],
 note="Amounts and timing of instalments may vary slightly by state. See the latest eligibility conditions on pmayg.nic.in.")
E("pm-awas-yojana-urban-2", name="Pradhan Mantri Awas Yojana – Urban 2.0 (PMAY-U 2.0)", short="Assistance up to ₹2.50 lakh to build/buy a house, or interest subsidy on home loans, for urban families.", tag="Urban housing", ministry="Ministry of Housing & Urban Affairs",
 facts=[("Period","2024 to 2029 (started 1 Sept 2024)"),("BLC / AHP assistance","Up to ₹2.50 lakh"),("Interest subsidy (ISS)","4% on first ₹8 lakh of loan"),("Income limit","EWS ₹3 lakh · LIG ₹3–6 lakh · MIG ₹6–9 lakh (yearly)")],
 about="PMAY-U 2.0 aims to provide homes to 1 crore urban families. It runs in four verticals: Beneficiary-Led Construction on own land (BLC), Affordable Housing in Partnership (AHP), Affordable Rental Housing (ARH) and Interest Subsidy Scheme on home loans (ISS). One vertical is chosen at application and cannot be changed later.",
 benefits=["BLC (building on own vacant land, EWS): up to ₹2.50 lakh","AHP (buying a house in a project, EWS): up to ₹2.50 lakh per unit","ARH: rental homes for urban migrants and low-income workers","ISS (EWS/LIG/MIG): 4% interest subsidy on first ₹8 lakh of home loan; limit of ₹25 lakh loan and ₹35 lakh house value for subsidy; maximum subsidy ₹1.80 lakh"],
 elig=["Annual family income: EWS up to ₹3 lakh, LIG ₹3–6 lakh, MIG ₹6–9 lakh","No family member owns a pucca house anywhere in India","Families who took an earlier housing scheme benefit are generally not eligible (about a 20-year condition; see official rules)"],
 notelig=["Families that own a pucca house anywhere","Families that took an earlier housing scheme benefit (as per rules)"],
 docs=["Aadhaar card (of family members)","Income proof / income declaration","Bank account details","House/land papers (land ownership for BLC)","Documents asked by the bank for a home loan"],
 steps=["Check your income and eligibility, confirm you have no pucca house","Pick the right vertical for you (ISS if you have a home loan)","Apply on the official portal of the Ministry of Housing & Urban Affairs or through an authorised bank/lender","Ask the lender how the subsidy will be credited to your loan account","Track the application with your assessment ID on PMAY-MIS / PMAY-U 2.0 citizen portal"],
 link_label="pmay-urban.gov.in – official portal", helpline="",
 faq=[("Is there a subsidy on home loans?","Yes, under the ISS vertical EWS/LIG/MIG families get 4% interest subsidy on the first ₹8 lakh of the loan, maximum ₹1.80 lakh."),("Can I apply in more than one vertical?","No, you must choose one vertical at the time of application and it cannot be changed later."),("Over how many years is the subsidy given?","Different sources give different timelines (5 to 12 years). Ask your bank/lender for the official rule.")],
 note="Subsidy conditions and period depend on government orders. Confirm with the official portal and your bank before applying.")
E("pm-vishwakarma-yojana", name="PM Vishwakarma Yojana", short="Training, ₹15,000 toolkit support and cheap loans for traditional artisans.", tag="Artisans", ministry="Ministry of MSME (with Skill, Housing-Urban and Finance ministries)",
 facts=[("Toolkit support","₹15,000"),("Training stipend","₹500 per day"),("Loan","₹1 lakh (first tranche) + ₹2 lakh (second tranche)"),("Interest","Concessional 5% (government interest support)")],
 about="PM Vishwakarma is for traditional artisans and craftspeople who work with hands and tools. After registration they get a PM Vishwakarma certificate and ID card, skill training, financial help to buy modern tools, collateral-free cheap credit and incentives for digital transactions.",
 benefits=["PM Vishwakarma certificate and ID card","₹500 per day stipend during basic skill training (advanced training also available)","₹15,000 toolkit support to buy modern tools","Collateral-free loan: first tranche ₹1 lakh, second tranche ₹2 lakh on repayment, at 5% concessional interest","Per-transaction incentive for digital payments and marketing support"],
 elig=["Aged at least 18 and self-employed in one of the 18 traditional trades listed in the scheme (e.g. carpenter, blacksmith, goldsmith, potter, cobbler, mason, tailor, barber, washerman, garland maker)","Work is in the unorganised sector with hands and tools","Only one member per family benefits","Has not taken a similar credit scheme such as PMEGP, PM SVANidhi or Mudra in the last 5 years"],
 notelig=["People in Central/State government jobs and their family members","Trades outside the scheme's list"],
 docs=["Aadhaar card","Mobile number linked to Aadhaar","Bank account details","Ration card (as needed)","Self-declaration / proof of craft"],
 steps=["Go to pmvishwakarma.gov.in or the nearest Common Service Centre (CSC)","Register with Aadhaar and mobile OTP and complete biometric verification","Choose your trade and fill in the details","After verification at Gram Panchayat/urban body and district level, receive the PM Vishwakarma certificate and ID card","Apply on the portal for training, toolkit and loan, and contact the bank"],
 link_label="pmvishwakarma.gov.in – official portal", helpline="",
 faq=[("How much loan does PM Vishwakarma give?","₹1 lakh in the first tranche and, after repaying it, ₹2 lakh in the second, at a concessional interest rate."),("How much is the toolkit support?","Up to ₹15,000 in financial help, given to buy tools."),("Can women apply?","Yes, women working in the listed traditional crafts are also eligible.")],
 note="The government can change listed trades, loan amount and interest rate. See the latest rules on pmvishwakarma.gov.in and do not pay anyone for registration.")
E("pm-svanidhi-yojana", name="PM SVANidhi Yojana (for street vendors)", short="Working-capital loans in three tranches for street vendors, scheme extended to 2030.", tag="Street vendor", ministry="Ministry of Housing & Urban Affairs",
 facts=[("Loan","Working-capital loan in three tranches"),("Next tranche","On repaying the previous one"),("Scheme period","Extended to March 2030"),("Credit card","UPI-linked RuPay card after repaying the second tranche")],
 about="PM SVANidhi is for street, cart and hawker vendors. It gives collateral-free working-capital loans in three tranches, and repaying each on time opens the way to the next, larger one. The scheme has been extended to March 2030 and widened to census towns and surrounding areas.",
 benefits=["Collateral-free working-capital loan in three tranches","Eligibility for the next tranche on repaying each one","After repaying the second tranche, a chance to apply for a UPI-linked RuPay credit card","Incentives such as cashback on digital transactions (amounts change from time to time)"],
 elig=["Vendors doing street/hawking work in urban areas","Identification by the state/urban local body (vending certificate / ID card or name in the survey) is required","The scheme now covers census towns and areas around urban centres"],
 notelig=["Those not recorded in an ID proof or survey (they must first register with the local body)"],
 docs=["Aadhaar card","Vending certificate / ID card (from local body)","Bank account details","Mobile number"],
 steps=["Find out your status of identification (survey/certificate) as a vendor with your municipal corporation/council","Apply on pmsvanidhi.mohua.gov.in or through a bank/CSC","The bank/lender sanctions the loan after verification","Repay on time to unlock the next tranche and the credit card option"],
 link_label="pmsvanidhi.mohua.gov.in – official portal", helpline="",
 faq=[("How much loan does SVANidhi give?","A working-capital loan in three tranches, with the next given on repaying each. See the exact tranche amounts with the bank or on the portal, as they changed after restructuring."),("Can I get it without a vending certificate?","Generally identification by the local body or a name in the survey is needed. Contact your municipal corporation/council."),("How do I get the credit card?","Vendors who fully repay the second tranche can apply for a UPI-linked RuPay credit card.")],
 note="Tranche amounts and conditions changed after restructuring, so amounts are not given here. Get the latest from pmsvanidhi.mohua.gov.in or your bank.")
E("pm-fasal-bima-yojana", name="Pradhan Mantri Fasal Bima Yojana (PMFBY)", short="Insurance for crop loss from natural calamities, with the farmer paying only 1.5% to 5% premium.", tag="Crop insurance", ministry="Ministry of Agriculture & Farmers Welfare",
 facts=[("Kharif (cereals/oilseeds)","2% premium"),("Rabi (cereals/oilseeds)","1.5% premium"),("Commercial/horticulture","5% premium"),("Official portal","pmfby.gov.in")],
 about="PMFBY protects farmers when crops are damaged by floods, drought, hailstorm, pests and diseases. The farmer pays only a small share of the sum insured as premium and the government pays the rest. Both loanee and non-loanee farmers can enrol voluntarily.",
 benefits=["Premium of 2% on kharif cereals/oilseeds, 1.5% on rabi, 5% on commercial/horticulture crops","Government subsidy on the remaining premium","Cover for prevented sowing, standing-crop loss, localised calamities like hailstorm/landslide/inundation, and post-harvest loss (for the notified period)"],
 elig=["Farmers growing notified crops (owners as well as tenants/sharecroppers)","Both loanee and non-loanee farmers","Insurable interest in the crop in a notified area is required"],
 notelig=["Loss caused by negligence or avoidable risk","War/nuclear risk","Loss of harvested crop after the notified period"],
 docs=["Aadhaar card","Land records or proof of sharecropping","Bank passbook / cancelled cheque","Sowing and crop details","Previous season's receipt on renewal"],
 steps=["Apply on pmfby.gov.in 'Farmer Corner', or at a bank branch, CSC or insurance company office","Choose season, crop, notified area and sum insured per hectare","Pay the farmer's share (premium)","Keep the receipt and application ID safe and link your mobile number","For localised calamity or post-harvest loss, inform the insurer, portal or CSC generally within 72 hours (period depends on state notification)"],
 link_label="pmfby.gov.in – official portal", helpline="",
 faq=[("How much premium do I pay for crop insurance?","Kharif cereals/oilseeds 2%, rabi 1.5% and commercial/horticulture 5% (of the sum insured)."),("What to do after a loss?","Report as soon as possible, generally within 72 hours, to the insurer/portal/CSC. The period may differ in the state notification."),("When is the last date to apply?","It differs by state and season. Kharif is usually around June–July and rabi around October–November. Check your state's latest date on the portal.")],
 note="Premium rates and last dates vary by state and season. Confirm with pmfby.gov.in or your bank before enrolling.")
E("pm-matru-vandana-yojana", name="Pradhan Mantri Matru Vandana Yojana (PMMVY)", short="₹5,000 for the first child and ₹6,000 if the second child is a girl.", tag="Maternity support", ministry="Ministry of Women & Child Development",
 facts=[("First child","₹5,000 (₹3,000 + ₹2,000)"),("Second girl child","₹6,000 (one instalment, after birth)"),("Apply","Anganwadi / health centre / pmmvy.wcd.gov.in"),("Income limit","None")],
 about="PMMVY gives cash support to pregnant and breastfeeding mothers for rest and nutrition. For the first living child a fixed amount is paid in two instalments, and if the second child is a girl, ₹6,000 is paid in one go. The money comes to the Aadhaar-linked bank account.",
 benefits=["Total ₹5,000 for the first child: ₹3,000 (on pregnancy registration) and ₹2,000 (after at least one antenatal check-up)","₹6,000 in one instalment if the second child is a girl","A separate incentive for institutional delivery may be available under Janani Suraksha Yojana"],
 elig=["Pregnant/breastfeeding woman for the first living child","Pregnancy must be registered at an Anganwadi centre or recognised health facility","Aadhaar-linked bank account","No income limit"],
 notelig=["Women employed in Central/State government or PSUs","Those already getting similar maternity benefit under another law","For the third or later child"],
 docs=["Aadhaar card","Aadhaar-linked bank passbook","Mother-Child Protection (MCP) card","Proof of pregnancy registration","ID proof (Aadhaar/Voter ID)","Child's birth certificate (for later instalment)","Consent/declaration form"],
 steps=["Register the pregnancy at the nearest Anganwadi centre or health centre (PHC/CHC) and get an MCP card","Fill the PMMVY application form and submit documents","The Anganwadi worker/ASHA-ANM enters details on the portal","Online: you can also apply on pmmvy.wcd.gov.in or the UMANG app; keep the reference number safe","After checks, instalments come to the Aadhaar-linked account"],
 link_label="pmmvy.wcd.gov.in – official portal", helpline="",
 faq=[("How much does PMMVY pay?","₹5,000 (₹3,000 + ₹2,000) for the first child and ₹6,000 if the second child is a girl."),("Do government employees get it?","No, women working in Central/State government or PSUs are not eligible."),("Whom to contact for help?","Your Anganwadi worker or the block PMMVY nodal officer, or lodge a complaint on pmmvy.wcd.gov.in.")],
 note="The number of eligible children and the amounts may change by government order. Confirm with the Anganwadi or pmmvy.wcd.gov.in before applying.")
E("e-shram-card", name="e-Shram Card (for unorganised workers)", short="National registration of unorganised workers, a 12-digit UAN and the route to social security schemes.", tag="Worker registration", ministry="Ministry of Labour & Employment",
 facts=[("Age","16 to 59 years"),("ID","12-digit unique UAN"),("Fee","Registration is free"),("Helpline","14434 / 1800-889-6811")],
 about="The e-Shram portal is the national database of unorganised workers (farm labourers, construction workers, domestic workers, vendors, drivers etc.). After registering you get an e-Shram card with a 12-digit Universal Account Number (UAN), which makes it easier to reach government social security schemes.",
 benefits=["A permanent 12-digit UAN and card valid across India","Easier to join social security schemes","Provision for benefits like accident insurance through the portal (as per terms; see the latest benefits on the portal)","Information on employment and skill schemes"],
 elig=["Unorganised sector worker aged 16 to 59","Mobile number linked to Aadhaar","Not an income taxpayer","Not a member of EPFO/ESIC (see latest rules on the portal)"],
 notelig=["Income taxpayers","Members of EPFO or ESIC","People above 59 years"],
 docs=["Aadhaar card","Mobile number linked to Aadhaar","Bank account details"],
 steps=["On eshram.gov.in choose 'Register on eShram'","Enter the Aadhaar-linked mobile number and captcha and get an OTP","Enter the OTP to complete Aadhaar e-KYC","Fill address, education, occupation, skill and bank details","Submit the self-declaration and download the e-Shram card (registration can also be done at a CSC)"],
 link_label="eshram.gov.in – official portal", helpline="Toll-free: 14434 or 1800-889-6811 (9 am to 6 pm)",
 faq=[("Is there a fee for the e-Shram card?","Self-registration on the portal is free. A CSC may charge a small service fee. Do not pay extra in the name of a government fee."),("Who cannot get it?","Income taxpayers and EPFO/ESIC members are not eligible, and age must be 16 to 59."),("What is a UAN?","The permanent 12-digit number you get after e-Shram registration, which works as identification across India.")],
 note="Benefits and eligibility rules linked to e-Shram keep changing. Check the latest list on eshram.gov.in or the helpline.")
E("pm-garib-kalyan-anna-yojana", name="Pradhan Mantri Garib Kalyan Anna Yojana (free ration)", short="Free monthly grain for eligible ration card holders, scheme extended to December 2028.", tag="Free ration", ministry="Ministry of Consumer Affairs, Food & Public Distribution",
 facts=[("PHH card","5 kg grain per person per month, free"),("AAY card","35 kg per family per month, free"),("Period","Extended to December 2028"),("Helpline","1967")],
 about="Under PMGKAY, ration card holders covered by the National Food Security Act (NFSA) get rice/wheat free every month. The benefit depends on the ration card category: Priority Household (PHH) and Antyodaya Anna Yojana (AAY) card holders are eligible.",
 benefits=["PHH card: 5 kg rice/wheat per person per month, free","AAY card: 35 kg per family per month, free, regardless of family size","Distribution through the ration shop (fair price shop)"],
 elig=["Only PHH and AAY ration card holders; eligibility is set by ration card category under NFSA","Generally BPL families, landless labourers, marginal farmers, rural artisans, slum dwellers and some widows/disabled/senior citizens/primitive tribes may be included"],
 notelig=["APL ration card holders are not included in this free ration scheme"],
 docs=["Aadhaar of all members (to make/add to a ration card)","Address proof","Income certificate (from Tehsildar/SDM, as per state rules)","Passport photo and mobile number"],
 steps=["Apply for a ration card on your state food department portal or at the nearest CSC (each state's process differs)","On nfsa.gov.in check your entitlement under 'Know Your Entitlement' and Aadhaar-link status","Find your ration shop on annavitran.nic.in or the 'Mera Ration' app","For complaints call the National Food Security helpline 1967"],
 link_label="nfsa.gov.in – official portal", helpline="National Food Security helpline: 1967",
 faq=[("Who gets free ration?","Those with a PHH or AAY ration card under NFSA. APL card holders do not get this scheme."),("What if I get less ration?","First check your entitlement on nfsa.gov.in, then complain on helpline 1967 or at your district supply office."),("Where is a ration card made?","On the state's Food & Supplies department portal or at a CSC. Each state's process differs.")],
 note="The scheme period and quantity depend on Central Government decisions. Confirm your state's position with nfsa.gov.in or the ration shop.")
